mapper.select:
select AA.portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioNamep, PTL_PORTFOLIO.PROFIT_TYPE profitType, PTL_PORTFOLIO.MDATE mdatep, fin_product_type.type_8 type8, fin_product.FINPROD_MARKET_ID finprodId, fin_product.FINPROD_ABBR finprodAbbr, fin_product.MDATE mdate, fin_product.CCY assetCcy, AA.invAim, (CASE WHEN fin_product_type.type_8 ='F01' THEN AA.amount*100 ELSE AA.amount END) amountp,
CC.shareAmt, EE.portfolioName, BB.dscCostAmt/BB.shareAmt price, BB.tdyIntincexp, BB.yield * 100 as yield, BB.exerYield * 100 as exerYield from (select PTL_SEC_POSITION.PORTFOLIO_ID portfolioId, PTL_SEC_POSITION.FINPROD_ID finprodId, PTL_SEC_POSITION.INV_AIM invAim, sum(PTL_SEC_POSITION.AMOUNT) amount from PTL_SEC_POSITION where PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{cdate},'%Y-%m-%d') and PTL_SEC_POSITION.HODING_TYPE = '03'
and PTL_SEC_POSITION.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and PTL_SEC_POSITION.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and PTL_SEC_POSITION.PORTFOLIO_ID not in
#{item}
and PTL_SEC_POSITION.FINPROD_ID not in
#{item}
group by PTL_SEC_POSITION.PORTFOLIO_ID,PTL_SEC_POSITION.FINPROD_ID,PTL_SEC_POSITION.INV_AIM ) AA inner join PTL_PORTFOLIO on AA.portfolioId = PTL_PORTFOLIO.PORTFOLIO_ID inner join fin_product on AA.finprodId = fin_product.FINPROD_ID inner join fin_product_type on fin_product.FINPROD_ID = fin_product_type.FINPROD_ID left join (select PTL_SEC_VALUTION.PORTFOLIO_ID portfolioId, PTL_SEC_VALUTION.FINPROD_ID finprodId, PTL_SEC_VALUTION.INV_AIM invAim, max(PTL_SEC_VALUTION.DSC_COST_AMT) dscCostAmt, max(PTL_SEC_VALUTION.SHARE_AMT) shareAmt, max(PTL_SEC_VALUTION.TDY_INTINCEXP) tdyIntincexp, max(PTL_SEC_VALUTION.YIELD) yield, max(PTL_SEC_VALUTION.EXER_YIELD) exerYield from PTL_SEC_VALUTION where PTL_SEC_VALUTION.CDATE = (select max(T.CDATE) from PTL_SEC_VALUTION T where T.PORTFOLIO_ID = PTL_SEC_VALUTION.PORTFOLIO_ID and T.CDATE < STR_TO_DATE(#{cdate},'%Y-%m-%d') )
and PTL_SEC_VALUTION.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and PTL_SEC_VALUTION.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
group by PTL_SEC_VALUTION.PORTFOLIO_ID,PTL_SEC_VALUTION.FINPROD_ID,PTL_SEC_VALUTION.INV_AIM ) BB on AA.portfolioId = BB.portfolioId left join (select MOCK_PRODUCT_DEAL.FINPROD_ID finprodId, sum(MOCK_PRODUCT_DEAL.SHARE_AMT) shareAmt from MOCK_PRODUCT_DEAL inner join MOCK_TEST on MOCK_PRODUCT_DEAL.MOCK_ID = MOCK_TEST.MOCK_ID where 1=1
and MOCK_PRODUCT_DEAL.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
group by MOCK_PRODUCT_DEAL.FINPROD_ID ) CC on AA.finprodId = CC.finprodId left join (select DD.FINPROD_ID finprodId, group_concat(DD.PORTFOLIO_NAME order by DD.PORTFOLIO_NAME separator ',') portfolioName from (select distinct MOCK_PRODUCT_DEAL.FINPROD_ID,PTL_PORTFOLIO.PORTFOLIO_NAME from MOCK_PRODUCT_DEAL inner join MOCK_TEST on MOCK_PRODUCT_DEAL.MOCK_ID = MOCK_TEST.MOCK_ID inner join PTL_PORTFOLIO on MOCK_TEST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID where 1=1
and MOCK_PRODUCT_DEAL.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) DD group by DD.FINPROD_ID ) EE on AA.finprodId = EE.finprodId where 1=1
and fin_product_type.TYPE_8 = #{type8,jdbcType=VARCHAR}
and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}
and PTL_PORTFOLIO.mdate >= STR_TO_DATE(#{mdateStart}, '%Y-%m-%d')
and PTL_PORTFOLIO.mdate <= STR_TO_DATE(#{mdateEnd}, '%Y-%m-%d')
and fin_product.mdate >= STR_TO_DATE(#{mdateStartzc}, '%Y-%m-%d')
and fin_product.mdate <= STR_TO_DATE(#{mdateEndzc}, '%Y-%m-%d')
and PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
